"C:\\Users\\ww\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$currentDirectory = (Get-Location).Path
Write-Output ('"'CurrentDirectory: ' + "'$currentDirectory)
$preflightPaths = @('"'.agents/skills/cineweave-director/SKILL.md', '.agents/skills/cineweave-director/references/optional/video-platform-adaptation.md', '.agents/skills/cineweave-director/references/optional/video-model-practices-2026-10.md')
foreach ("'$preflightPath in $preflightPaths) {
    $preflightHash = Get-FileHash -LiteralPath $preflightPath -Algorithm SHA256 -ErrorAction Stop
    $preflightText = Get-Content -LiteralPath $preflightPath -Raw -Encoding UTF8 -ErrorAction Stop
    $replacementCount = 0
    foreach ($preflightCharacter in $preflightText.ToCharArray()) {
        if ([int]$preflightCharacter -eq 0xFFFD) { $replacementCount++ }
    }
    [pscustomobject]@{ Path = $preflightPath; SHA256 = $preflightHash.Hash; U_FFFD_Count = $replacementCount } | Format-List
}'

